"use client";

import { motion, useReducedMotion } from "motion/react";
import type { ComponentProps } from "react";

export type AnticipationPrimitiveProps = ComponentProps<typeof motion.div>;

export function AnticipationPrimitive({ children, ...props }: AnticipationPrimitiveProps) {
  const reduceMotion = useReducedMotion();

  return (
    <motion.div
      {...props}
      initial={reduceMotion ? false : {scale: 1}}
      animate={{scale: [1,0.96,1.04,1]}}
      transition={reduceMotion ? { duration: 0.12 } : { duration: 0.52, ease: [0.23, 1, 0.32, 1] }}

    >
      {children}
    </motion.div>
  );
}
